bool issquare(long long x) {
    if (x <= 0) return false;
    long long r = sqrtl(x);
    while ((r + 1) * (r + 1) <= x) r++;
    while (r * r > x) r--;
    return r * r == x;
}

bool iscube(long long x) {
    if (x <= 0) return false;
    long long r = cbrtl(x);
    while ((r + 1) * (r + 1) * (r + 1) <= x) r++;
    while (r * r * r > x) r--;
    return r * r * r == x;
}

bool ispower(long long x, int p) {
    if (x <= 0) return false;

    long long r = pow((long double)x, 1.0L / p);

    for (long long t = max(1LL, r - 2); t <= r + 2; t++) {
        long long cur = 1;
        for (int i = 0; i < p; i++) cur *= t;
        if (cur == x) return true;
    }
    return false;
}

bool twosquares(long long x) {
    if (x <= 0) return false;

    for (long long p = 2; p * p <= x; p++) {
        if (x % p) continue;

        int cnt = 0;
        while (x % p == 0) {
            x /= p;
            cnt++;
        }

        if (p % 4 == 3 && (cnt & 1)) return false;
    }

    return x % 4 != 3;
}

bool threesquares(long long x) {
    if (x <= 0) return false;
    while (x % 4 == 0) x /= 4;
    return x % 8 != 7;
}

int solve(long long n) {
    if (issquare(n)) return 2;
    if (iscube(n)) return 3;
    if (twosquares(n)) return 4;

    if (ispower(n, 5)) return 5;
    for (long long i = 1; i * i * i < n; i++) {
        if (issquare(n - i * i * i)) return 5;
    }

    for (long long i = 1; i * i * i < n; i++) {
        if (iscube(n - i * i * i)) return 6;
    }
    if (threesquares(n)) return 6;

    if (ispower(n, 7)) return 7;
    for (long long i = 1; i * i * i < n; i++) {
        if (twosquares(n - i * i * i)) return 7;
    }

    return 8;
}

int main() {
    int t;
    cin >> t;

    while (t--) {
        long long n;
        cin >> n;
        cout << solve(n) << '\n';
    }
}